// Successor-first failed to install a real consumer. Fall back to the
// V3.51 stale-path retirement boundary rather than leaving an old mover
// route live under the new Follow generation.
bot.Mover.BotMoverStop("R1-1FEC86422402", @bot)

// Retire stale native route topology only; re-anchor to the measured
// body before requesting a fresh Follow route. No body relocation or
// forced-forward locomotion, no additional writer generation.
bot.Mover.BotMoverStop("R1-8C421A090980", @bot)

// TryVaulting() normally performs this handoff before the animator bool is set.
// Injected Vault intentionally skips the scanner/TryVaulting path, so reproduce the
// non-scanner side effect explicitly and publish transport-neutral network intent.
probe.Player.PlayerRemoveLeftHandItem("R1-0913BFCCC600", @probe?.Bot, 2f)

// RC66: RC62 computed a same-chain DropDown speed envelope, but
// preserveSprintMode previously replaced it with FULL speed.
// Respect the already-computed bound for this exact native
// predecessor only. Never mutate the Jump Sprint reservation,
// change the successor admission, or stop vertical descent.
bot.BotOwnerSetTargetMoveSpeed("R1-595C61E35121", @bot, sameChainDropDownNativeEnvelope ? precisionSpeed : (bot.Mover.Sprinting ? ProbeMomentumFullMoveSpeed : (probe.PreviousRunning ? ProbeMomentumNormalMoveSpeed : precisionSpeed)))

// Flush the residual approach vector too. Fix32 already stopped BotMover, but
// runtime still showed the native Jump/Transition writer moving the body ~40 ms
// later; zero ApplyApproachMotion keeps MovementContext itself synchronized while
// the landing state settles.
probe.Player.MovementContext.TryMovementContextApplyApproachMotion("R1-734287B9F7AB", @probe?.Bot, Vector3.zero, Mathf.Max(0.001f, Time.deltaTime))

// Sprint(false) is the native BotMover command. Never write the
// MovementContext sprint flag, animator, position, or NavMesh anchor.
bot.Mover.BotMoverSprint("R1-0043E072ECD3", @bot, false, false)

// EFT BotMover.Teleport() updates PositionOnWayInner and calls AllowTeleport(),
// but it does NOT update PrevSuccessLinkedFrom_1. Once AllowTeleport is consumed,
// method_12 can therefore reconnect the body to that historical point. V432
// commits the native mover's linked epoch in the same relocation transaction.
bot.Mover.BotMoverTeleport("R1-701B4E0164EB", @bot, target)

// Retire the previously chosen long-detour BotMover target
// once. Keeping it alive competes with exact world-space
// Player.Move even while Follow owns the only write scope.
bot.Mover.BotMoverStop("R1-9D804919CCB8", @bot)

// Keep manual BotMover routing from overriding the already
// issued single-writer world-space input in this frame.
bot.Mover.SetBotMoverPause("R1-9E289028D9EF", @bot, true)

// Cancel stale BotMover translation ONCE before
// returning to the V475 collision-active writer.
bot.Mover.BotMoverStop("R1-3A3481B816D8", @bot)

// State-only epoch scrub. Do NOT call Teleport, method_10, SetPlayerToNavMesh,
// CharacterController.Move, or any other body relocation writer here.
bot.Mover.SetBotMoverPositionOnWayInner("R1-9B0F994D1A8D", @bot, anchor)

// A fresh accepted path starts locally at this body and local NavMesh evidence is
// within the same native method_10 radius. It is now safe to commit native link
// bookkeeping without invoking any native body relocation method.
bot.Mover.SetBotMoverLinkedToNavmeshInitially("R1-D0CE879B43B4", @bot, true)

// V351 retires the stale producer instead of adding another relocation writer.
// Stop the old path, neutralize its destination/avoidance residue at the current
// authoritative body, and let the NEXT owner install a fresh path from here.
// No Teleport/CharacterController relocation is introduced at this boundary.
bot.Mover.BotMoverStop("R1-D527961E3CB0", @bot)

// Precision approach is always non-sprinting. Climb specifically requires this,
// while Vault receives the demonstrated forward velocity again at native trigger.
probe.Bot.Mover.BotMoverSprint("R1-26A0367D1ABC", @probe?.Bot, false, false)

// V3.4 only does this after acquisition has physically crossed the passage commit
// threshold. This is intentionally different from CompileFix45.1, which stopped the
// Mover BEFORE the ledge and froze every DropDown. Here the body is already through
// the boundary, so Stop() is used once to discard the stale near-side path topology,
// then the ordinary Mover is rebuilt from the current body position to rawExit.
probe.Bot.Mover.SetBotMoverPause("R1-D80E67B0D7D8", @probe?.Bot, false)

// Collision remains active. The raised capsule probe above must be clear before
// any vertical component is applied, so this cannot be used as a wall-phase path.
player.MovementContext.TryMovementContextApplyApproachMotion("R1-37E8988B2772", @probe?.Bot, step, dt)

// Collision remains fully active. ApplyApproachMotion moves through EFT's normal
// character controller and therefore cannot phase through the narrow corner wall;
// unlike BotMover it does not require a NavMesh polygon at the turn apex.
player.MovementContext.TryMovementContextApplyApproachMotion("R1-3DE0A70F7C6B", @probe?.Bot, step, dt)

// CompileFix26: entering WalkThrough is a rolling authority handoff. Do not Stop()
// the body just to replace the short mover target; that was visible as a hitch before
// every private-corridor traversal.
probe.Bot.BotOwnerSetPose("R1-A700B5015130", @probe?.Bot, 1f)

// V331 actually installed PathComplete earlier in THIS active
// probe. The next ledge revoked the landing candidate, not the
// prior producer identity. Do not synthesize another V414
// straight-ahead command when its short Mover target completes.
// With no live native path, retire stale predecessor input
// even through a second airborne epoch. Gravity/inertia remain
// native; no movement teleport or physical success is asserted.
// This may momentarily pause if no valid successor exists;
// the existing Native timeout and bounded recovery remain live.
probe.Bot.Mover.SetBotMoverPause("R1-D367399537CC", @probe?.Bot, false)

// Assisted V2 owns the crossing continuously. Clear the stale entry path without
// calling BotOwner.StopMove(); HoldForwardInput keeps locomotion alive while the
// old NavMesh route can no longer pull the follower back after landing.
probe.Bot.Mover.BotMoverStop("R1-8873CD326EC9", @probe?.Bot)

// Animation/state first: keep facing/locomotion coherent for a few frames before
// positional fallback begins. This is intentionally short so a missing/rootless
// animation can never strand the follower.
probe.Bot.Mover.SetBotMoverPause("R1-B202DEF233CE", @probe?.Bot, false)

// CharacterController.Move is already used by PIT's soft-collision system and keeps
// EFT world collision active. Unlike ApplyApproachMotion, it can own the vertical
// lift phase instead of having the first diagonal step cancelled by the wall.
probe.Player.CharacterController.TryICharacterControllerMove("R1-002B1679A1E2", @probe?.Bot, motion, deltaTime)

// Navigation-backed continuation is allowed only after its native path origin is
// rebased to the current physical body. Do not hard-stop a healthy traversal
// transaction merely to clear stale native path bookkeeping.
probe.Bot.Mover.SetBotMoverPause("R1-88D5645D06F3", @probe?.Bot, false)

// CompileFix26: clear only traversal animator triggers. Do not zero locomotion input
// or Stop/StopMove the follower on every successful exit. The zero-distance mover
// rebase is still retained because it is the proven snapback fix, but ordinary
// locomotion intent stays live across the authority transfer.
probe.Player.MovementContext.MovementContextPlayerAnimatorSetDoVault("R1-59FCF5ABCB03", @probe?.Bot, false)

// Retire a stale pre-traversal destination without stopping the character; a
// fresh Follow target is prewarmed below.
probe.Bot.GoToSomePointData.BotGoToPointDataSetPoint("R1-D7D9EBD9073A", @probe?.Bot, anchor)

// This is intentionally a zero-distance relocation. SafeTeleport already uses
// BotMover.Teleport because EFT updates PositionOnWayInner/AllowTeleport there;
// the purpose here is to rebase mover authority to the physical far-side body,
// not to visually move the follower.
probe.Bot.Mover.BotMoverTeleport("R1-EFB80A0B501C", @probe?.Bot, anchor)

// Cancel any pending animator trigger before arming teleport. Otherwise a
// delayed ClimbOver transition can start after the teleport commit and write
// root motion from the old traversal transaction back into the new position.
probe.Player.MovementContext.MovementContextPlayerAnimatorSetDoVault("R1-2DE211E46BE0", @probe?.Bot, false)

// Safe step-off uses EFT's MovementContext/character controller: no transform write,
// teleport, layer change or collision disable occurs here.
player.MovementContext.TryMovementContextApplyApproachMotion("R1-2726268BA2BE", @probe?.Bot, direction * stepDistance, deltaTime)

// V3.57 extends successor-first continuity across bounded ordinary ground
// segments. Never convert a Sprint boundary into Stop/Pause; taper to Run and
// let the successor/route producer take over on the next writer generation.
probe.Bot.Mover.SetBotMoverPause("R1-41126A00D218", @probe?.Bot, false)
